  }
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!db.prepare('SELECT id FROM projects WHERE id = ?').get(projectId)) return send(404, JSON.stringify({ error: 'Project not found' }));
    if (req.method === 'GET') {
      const tasks = db.prepare('SELECT id, title, completed, priority, due_date, notes FROM tasks WHERE project_id = ? ORDER BY position, id').all(projectId);
      return send(200, JSON.stringify(tasks.map(task => ({ ...task, completed: Boolean(task.completed) }))));
    }
    if (req.method === 'POST') {
      if (db.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId).archived) return send(400, JSON.stringify({ error: 'Archived project' }));
      let body = '';
      for await (const chunk of req) body += chunk;
      try {
        const title = String(JSON.parse(body).title ?? '').trim();
        if (!title) return send(400, JSON.stringify({ error: 'Task title is required' }));
        const priority = db.prepare('SELECT default_priority FROM projects WHERE id = ?').get(projectId).default_priority;
        const result = db.prepare('INSERT INTO tasks (project_id, title, priority, position) VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?))').run(projectId, title, priority, projectId);
        const taskId = Number(result.lastInsertRowid);
        const position = db.prepare('SELECT position FROM tasks WHERE id = ?').get(taskId).position;
        db.prepare('INSERT INTO task_project_positions (task_id, project_id, position) VALUES (?, ?, ?)').run(taskId, projectId, position);
        return send(201, JSON.stringify({ id: taskId, title, completed: false, priority }));
      } catch { return send(400, JSON.stringify({ error: 'Invalid request' })); }
    }
  }
  const moveRoute = url.pathname.match(/^\/api\/tasks\/(\d+)\/move$/);
  if (moveRoute && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    try {
      const destinationId = Number(JSON.parse(body).destinationProjectId);
      const taskId = Number(moveRoute[1]);
      const task = db.prepare('SELECT project_id FROM tasks WHERE id = ?').get(taskId);
